'use strict';
const $=id=>document.getElementById(id);let demo=false,token='',connected=false,selected=null,busy=false;
const titles={overview:['Console overview','A clear view of your console, close to home.'],library:['Applications','Discover what’s on your console. Launch with confidence.'],plugins:['Plugin adapters','A dedicated home for console-side extensions.'],activity:['Session activity','A record of this session’s connection and launch actions.']};
function notice(t){$('notice').textContent=t}function log(t){if($('events').firstElementChild?.textContent==='No actions yet.')$('events').replaceChildren();let li=document.createElement('li'),time=document.createElement('time');time.textContent=new Date().toLocaleTimeString();li.append(time,document.createTextNode(t));$('events').prepend(li)}
function view(v){document.querySelectorAll('.view').forEach(e=>e.hidden=e.id!==v);document.querySelectorAll('nav button').forEach(e=>e.classList.toggle('active',e.dataset.view===v));$('crumb').textContent=v==='library'?'Applications':v[0].toUpperCase()+v.slice(1);$('page-title').replaceChildren(document.createTextNode(titles[v][0]),Object.assign(document.createElement('span'),{textContent:'.'}));$('page-description').textContent=titles[v][1]}
for(const b of document.querySelectorAll('[data-view]'))b.onclick=()=>view(b.dataset.view);for(const b of document.querySelectorAll('[data-goto]'))b.onclick=()=>view(b.dataset.goto);
for(const b of document.querySelectorAll('.close'))b.onclick=()=>b.closest('dialog').close();
async function api(action,data={}){const r=await fetch('/api/'+action,{method:'POST',headers:{'Content-Type':'application/json','Authorization':'Bearer '+token},body:JSON.stringify(data)});let j;try{j=await r.json()}catch{throw Error('Open the app using the URL printed by your local bridge.')}if(!r.ok)throw Error(j.error||'The bridge could not complete this action.');return j}
async function task(fn){if(busy)return;busy=true;try{await fn()}catch(e){notice(e.message);if(!connected){$('connection-label').textContent='Not connected';$('mode').textContent='OFFLINE';$('metric-status').textContent='Offline';$('console-name').textContent='Connection required';$('console-note').textContent='Check the bridge and reconnect.';$('footer-mode').textContent='Local connection required'}log('Action failed: '+e.message)}finally{busy=false}}
function status(s){connected=true;$('connection-label').textContent=demo?'Demo console':'Console connected';$('console-name').textContent=demo?'Demo workspace':'Console connected';$('console-note').textContent=demo?'Sample data only. No console commands are sent.':'Neighborhood connection is ready.';$('mode').textContent=demo?'DEMO':'CONNECTED';$('metric-status').textContent=demo?'Demo':'Connected';$('metric-type').textContent=s.type||'Unavailable';$('metric-kernel').textContent=s.kernel||'Unavailable';$('metric-drives').textContent=s.drives.length;$('footer-mode').textContent=demo?'Demo · sample data':'Local session · private data excluded';$('connect').textContent='Change connection';const prev=$('drive').value;$('drive').replaceChildren();for(const d of s.drives){const o=document.createElement('option');o.value=d;o.textContent=d;$('drive').append(o)}if(s.drives.includes(prev))$('drive').value=prev;$('path').value=$('drive').value;}
function connectDialog(){$('hosted-help').hidden=location.hostname==='127.0.0.1'||location.hostname==='localhost'||/^192\.168\.|^10\.|^172\.(1[6-9]|2\d|3[01])\./.test(location.hostname);$('connection-dialog').showModal()}
$('connect').onclick=connectDialog;$('connection-open').onclick=connectDialog;
$('connection-form').onsubmit=e=>{e.preventDefault();task(async()=>{token=$('token').value.trim();demo=false;connected=false;selected=null;$('connection-label').textContent='Connecting…';$('mode').textContent='CONNECTING';$('metric-status').textContent='Connecting';$('metric-type').textContent='—';$('metric-kernel').textContent='—';$('metric-drives').textContent='—';$('files').replaceChildren();const s=await api('connect',{target:$('target').value.trim()});status(s);$('connection-dialog').close();notice('Connected. Choose a discovered storage root to browse applications.');log('Neighborhood connection established.');$('token').value='';})};
$('demo').onclick=()=>{demo=true;token='';status({type:'Retail (sample)',kernel:'2.0.17559.0',drives:['DemoDisk:\\','DemoUSB:\\']});notice('Demo mode — sample data, no connection to a real console.');log('Demo mode enabled.');};
$('drive').onchange=()=>{$('path').value=$('drive').value;task(browse)};
const samples=[{name:'Games',directory:true},{name:'Homebrew',directory:true},{name:'Plugins',directory:true},{name:'Nebulah',directory:true}];
function demoFiles(path){if(/^[^\\]+\\$/.test(path))return samples;if(/Games/i.test(path))return [{name:'default.xex',size:12582912}];if(/Plugins/i.test(path))return [{name:'sample-plugin.xex',size:524288}];return [{name:'default.xex',size:2097152},{name:'readme.txt',size:2048}]}
async function browse(){if(!connected)throw Error('Connect a console or choose Explore demo first.');const path=$('path').value;const r=demo?{files:demoFiles(path)}:await api('browse',{path});$('files').replaceChildren();if(!r.files.length){const d=document.createElement('div');d.className='empty-state';d.textContent='This directory is empty.';$('files').append(d)}for(const f of r.files){const row=document.createElement('div');row.className='file-row';const icon=document.createElement('span');icon.className='file-icon';icon.textContent=f.directory?'▱':'◇';const meta=document.createElement('div'),name=document.createElement('b'),sub=document.createElement('small');name.textContent=f.name;sub.textContent=f.directory?'Directory':Math.ceil((f.size||0)/1024).toLocaleString()+' KB';meta.append(name,sub);row.append(icon,meta);if(f.directory||/\.xex$/i.test(f.name)){const b=document.createElement('button');b.className='secondary';b.textContent=f.directory?'Open →':'Inspect XEX';b.onclick=()=>task(async()=>{const full=path.replace(/\\?$/,'\\')+f.name;if(f.directory){$('path').value=full+'\\';await browse()}else await inspect(full)});row.append(b)}$('files').append(row)}log(demo?'Demo directory opened.':'Console directory opened.');}
$('browse').onclick=()=>task(browse);$('up').onclick=()=>task(async()=>{const p=$('path').value.replace(/\\$/,'');const i=p.lastIndexOf('\\');if(i>=0){$('path').value=p.slice(0,i+1);await browse()}});
async function inspect(path){selected=null;$('launch').disabled=true;$('launch-path').textContent=path;$('validation').textContent='Reading and checking XEX…';$('launch-dialog').showModal();try{const v=demo?{valid:true,plugin:/Plugins/i.test(path),hash:'Demo only — no file was read',ticket:'demo',checks:['XEX2 header (sample)','Header bounds (sample)','Application module (sample)']}:await api('validate',{path});selected={...v,path};$('validation').replaceChildren();for(const text of [...v.checks,'SHA-256: '+v.hash,v.plugin?'Plugin module: runtime loader required.':'Application candidate. Structural checks passed.']){const d=document.createElement('div');d.className='validation-row mono';d.textContent=text;$('validation').append(d)}$('launch').disabled=!v.valid||v.plugin;$('launch').textContent=demo?'Simulate launch →':'Launch application →';log(demo?'Demo XEX inspection completed.':'XEX structural inspection completed.')}catch(e){$('validation').textContent=e.message;throw e}}
$('launch').onclick=()=>task(async()=>{if(!selected||!selected.valid||selected.plugin)return;$('launch').disabled=true;if(!demo)await api('launch',{ticket:selected.ticket});$('launch-dialog').close();notice(demo?'Simulated launch complete. Nothing was sent to a console.':'Launch command accepted. The console may disconnect while the title starts.');log(demo?'Launch simulated.':'Launch command accepted.');selected=null});
$('refresh').onclick=()=>task(async()=>{if(!connected)throw Error('Connect your console first.');if(!demo)status(await api('status'));notice(demo?'Demo data refreshed.':'Console status refreshed.');});$('clear').onclick=()=>{$('events').replaceChildren();log('Activity cleared.');};
